"""Render fictional illustrated everyday cases from public editorial data."""
import json
from html import escape
from pathlib import Path

root = Path(__file__).parent
cases = json.loads((root / 'everyday-cases.json').read_text())['cases']
cards = []
for case in cases:
    e = lambda key: escape(case[key])
    image = './assets/alltag-' + e('id') + '.webp'
    cards.append(f'''<article class="card everyday-case" id="bildfall-{e('id')}">
<figure><a href="{image}" data-case-picture aria-haspopup="dialog" aria-label="Bild vergrößern: {e('title')}"><img src="{image}" alt="{e('alt')}" width="1536" height="1024" loading="lazy" decoding="async"><span class="everyday-enlarge">Bild vergrößern</span></a><figcaption>KI-generierte Illustration · frei erfundene Szene</figcaption></figure>
<div class="everyday-case-body"><span class="pill">{e('topic')}</span><h3>{e('title')}</h3><p>{e('situation')}</p>
<details><summary>Hilfe und Abrechnung Schritt für Schritt</summary><h4>So sieht die Hilfe aus</h4><p>{e('help')}</p><h4>{e('route')}</h4><p>{e('billing')}</p><div class="equation">{e('equation')}</div><h4>So wird es nachvollziehbar</h4><p>{e('record')}</p><h4>Diese Grenze beachten</h4><p>{e('boundary')}</p><p class="small"><a href="#{e('source')}">{e('sourceLabel')}</a></p></details></div></article>''')
navigation = ''.join(f'<a href="#bildfall-{escape(c["id"])}">{escape(c["topic"])}</a>' for c in cases)
everyday_cases_html = '''<section id="alltagsbeispiele" class="household-help" aria-labelledby="everydayCasesTitle"><div class="section-title"><span class="number">Mit Bildern</span><div><h2 id="everydayCasesTitle">So kann Alltagshilfe konkret aussehen</h2><p>Sechs erfundene Situationen: Was braucht die Person, wie hilft jemand, und welcher Abrechnungsweg kann passen?</p></div></div><p>Die Personen bestimmen nach ihren Möglichkeiten mit. Hilfe kann entlasten und gleichzeitig eigene Fähigkeiten erhalten. Öffnen Sie unter dem Bild die Erklärung oder tippen Sie auf das Bild, um es größer anzusehen.</p><nav class="jump everyday-case-nav" aria-label="Bebilderte Alltagssituationen">''' + navigation + '''</nav><p class="notice household-note"><span><strong>Jedes Beispiel rechnet für sich.</strong> Personen, Preise und Guthaben sind frei erfunden. Die Entlastungsbeispiele beginnen jeweils mit 131 € eigenem Guthaben; sie sind keine gemeinsame Monatsplanung. Die Pflegekasse prüft Anbieter, Leistung, Belege und verfügbares Budget. Für Ersatzpflege gelten andere Voraussetzungen.</span></p><div class="grid2 everyday-case-grid">''' + ''.join(cards) + '''</div><details class="card everyday-common"><summary>Was gilt für alle Beispiele?</summary><p>Ein Pflegegrad allein macht eine beliebige Rechnung nicht erstattungsfähig. Beim Entlastungsbetrag muss die konkrete Leistung über einen geeigneten gesetzlichen Weg laufen; bei Alltagsangeboten muss sie vom anerkannten Leistungsumfang umfasst sein. Ehrenamtliche Nachbarschaftshilfe in Niedersachsen hat eigene Voraussetzungen. Die notwendige Verhinderung einer privaten Pflegeperson wird nur beim Weg über Verhinderungspflege vorausgesetzt.</p><p>Datum, tatsächliche Helferzeit, ausgeführte Tätigkeit und Vergütung dokumentieren. Waren und ausgeschlossene Arbeiten getrennt ausweisen. Keine Doppelerstattung derselben Kosten. Die Bilder veranschaulichen Situationen und ersetzen keine Prüfung des individuellen Hilfebedarfs.</p><p><a href="#nachbarschaft">Nachbarschaftshilfe und amtlicher Nachweis</a> · <a href="#boegen">Ausfüllbare Abrechnungsbögen</a> · <a href="#s-haus-land">Landesregeln zu Alltagshilfe</a> · <a href="#s-haus-recht">Gesetzliche Grundlagen</a></p></details></section>
<dialog id="everydayImageDialog" class="app-dialog everyday-image-dialog" aria-labelledby="everydayImageTitle"><div class="app-dialog-head"><h2 id="everydayImageTitle">Alltagshilfe im Bild</h2><button type="button" id="everydayImageClose" class="subtle">Bild schließen</button></div><div class="everyday-image-actions"><button type="button" id="everydayImageZoom" class="subtle" aria-pressed="false" aria-controls="everydayImageScroll">Bilddetails vergrößern</button><a id="everydayImageOriginal" target="_blank" rel="noopener">Originalbild öffnen</a></div><div id="everydayImageScroll" class="everyday-image-scroll" role="region" aria-label="Bildansicht, vergrößerte Ausschnitte können verschoben werden" tabindex="0"><img id="everydayImage" alt=""></div><p>KI-generierte Illustration einer frei erfundenen Situation. Mit „Bild schließen“ oder Escape zur Fallkarte zurückkehren.</p></dialog>'''
